    for line in open(p, encoding="utf-8"):
        s = line
        # strip comments with nesting, track depth
        out = []; i = 0
        while i < len(s):
            if s.startswith("(*", i): depth += 1; i += 2; continue
            if s.startswith("*)", i) and depth > 0: depth -= 1; i += 2; continue
            if depth == 0: out.append(s[i])
            i += 1
        t = "".join(out)
        if not t or t[0].isspace(): continue
        m = re.match(r'(opr\s+\S+?|[A-Za-z_][A-Za-z0-9_\']*)\s*(\[\\|\()', t)
        if m and not t.startswith(("object","trait","import","export","api","component","end","value")):
            c[m.group(1)] += 1
    return c
